private enum AuditHistoryStore {
    nonisolated(unsafe) static var saved = PersonalHistory()
    static func load() -> PersonalHistory { saved }
    static func save(_ h: PersonalHistory) { saved = h }
    static func publish(_ h: PersonalHistory) {}
    static func claimImport() -> PersonalHistory? { nil }
}

final class HistoryLifecycleAuditTests: XCTestCase {
    func testHistoryAndSplitImports() throws {
        guard let output = ProcessInfo.processInfo.environment["KB_HISTORY_AUDIT"] else {
            throw XCTSkip("Set KB_HISTORY_AUDIT to export diagnostics")
        }
        var rows: [[String:String]] = []
        for (name, inputs) in [
            ("duplicate_callback_control", ["dün akşam ", "dün akşam "]),
            ("extra_spaces", ["dün akşam ", "dün akşam  ", "dün akşam   "]),
            ("erase_then_retype", ["dün akşam ", "", "dün ", "dün akşam "]),
            ("two_word_single_event_insert", ["dün akşam ", "", "dün akşam "]),
            ("new_field_single_word", ["merhaba ", "", "m", "me", "merhaba", "merhaba "]),
            ("newline_boundary", ["dün akşam\n", "dün akşam\nbugün "]),
            ("single_word_control", ["merhaba "])
        ] {
            AuditHistoryStore.saved = PersonalHistory()
            let h = AuditTypingHistory()
            for input in inputs {
                if input.isEmpty { h.refreshImports() }
                h.observe(before: input)
            }
            h.flush()
            let saved = AuditHistoryStore.saved
            rows.append(["case":name,"inputs":inputs.joined(separator:" | "),
                         "aksam_count":String(saved.tokens["akşam"]?.count ?? 0),
                         "merhaba_count":String(saved.tokens["merhaba"]?.count ?? 0),
                         "dun_aksam_pair_count":String(saved.pairs["dün"]?["akşam"]?.count ?? 0),
                         "next_after_aksam":saved.nextWords(after:"akşam").joined(separator:" | ")])
        }
        var bulk = PersonalHistory()
        bulk.observe(text:"dün akşam\nbugün ")
        rows.append(["case":"bulk_newline_control","next_after_aksam":bulk.nextWords(after:"akşam").joined(separator:" | ")])
        for chunks in [[1,1,1], [2,1], [3], [3,3]] {
            var p = PersonalLexicon()
            for count in chunks { p.ingest(tokens:Array(repeating:"qrmenü",count:count),isKnown:{ _ in false }) }
            rows.append(["case":"split_personal_import", "chunks":String(describing:chunks),
                         "points":String(p.entries["qrmenü"]?.points ?? 0),"admitted":String(p.isAdmitted("qrmenü"))])
        }
        let enc = JSONEncoder(); enc.outputFormatting = [.prettyPrinted,.sortedKeys]
        try enc.encode(rows).write(to:URL(fileURLWithPath:output))
        print("HISTORY AUDIT: \(rows.count) scenarios")
    }
}

final class AuditTypingHistory {
    /// Bu kadar gözlemde bir diske yazılıyor (her kelimede yazmak pahalı).
    private static let saveEvery = 20

    private lazy var history = AuditHistoryStore.load()
    private var lastObserved: (token: String, previous: String?, length: Int)?
    private var unsaved = 0

    /// Aynı klavye süreci yeniden görünse de uygulamadaki yeni aktarımı alır.
    func refreshImports() {
        _ = history // Tembel yükleme ilk aktarımı zaten sahiplenebilir.
        if let imported = AuditHistoryStore.claimImport() {
            history.merge(imported)
            unsaved += 1
            flush()
        }
        AuditHistoryStore.publish(history)
    }

    /// `before`: imleçten önceki metin; boşlukla bitmiyorsa kelime bitmemiş.
    func observe(before: String) {
        guard let lastChar = before.last, lastChar.isWhitespace else { return }
        let toks = PersonalHistory.tokenize(before)
        guard let token = toks.last else { return }
        let prev = toks.count >= 2 ? toks[toks.count - 2] : nil
        // Aynı sınır birden çok kez bildirilebiliyor; bir kez say.
        if let l = lastObserved, l.token == token, l.previous == prev, l.length == before.count { return }
        lastObserved = (token, prev, before.count)
        history.observe(token: token, previous: prev)
        unsaved += 1
        if unsaved >= Self.saveEvery { flush() }
    }

    /// Bir metnin tamamından öğrenir (alandan içe aktarma).
    func ingest(text: String) {
        history.observe(text: text)
        unsaved += 1
        flush()
    }

    func flush() {
        guard unsaved > 0 else { return }
        AuditHistoryStore.save(history)
        unsaved = 0
    }

    /// Boşlukla biten metinden sonra gelebilecek kelimeler.
    func nextWords(before: String) -> [String] {
        guard before.last == " ", let prev = PersonalHistory.tokenize(before).last,
              PersonalHistory.isWord(prev) else { return [] }
        return history.nextWords(after: prev)
    }

    /// Yazılan önekle başlayan, daha önce yazılmış tam token (IP, e-posta…).
    /// Önek geçmişin sakladığı biçimde: uç noktalama atılmış ("(192.16" → "192.16").
    func recall(lastToken raw: String) -> (prefix: String, full: String)? {
        guard let last = PersonalHistory.tokenize(raw).last, raw.hasSuffix(last),
              let full = history.recall(prefix: last).first else { return nil }
        return (last, full)
    }
}
